import java.util.*;
import java.util.Comparator;
public class AdjustOps {
    public static void main(String[] args) {
        List<Integer> xs = Arrays.asList(3, 1, 2, 3, 5, 4);
        System.out.println(xs.stream().distinct().sorted().toList());
        System.out.println(xs.stream().skip(1).limit(3).toList());
        System.out.println(xs.stream().sorted(Comparator.reverseOrder()).findFirst().orElse(-1));
        System.out.println(xs.stream().mapToInt(Integer::intValue).average().orElse(0));
        System.out.println(xs.stream().takeWhile(x -> x < 5).toList());
    }
}

