        System.out.println(Stream.iterate(0, i -> i + 1).anyMatch(i -> i > 5));
    }
}

import java.util.*;
import java.util.stream.*;
public class CollectorsDemo {
    record Stu(String name, String city, int score) {}
    public static void main(String[] args) {
        List<Stu> xs = List.of(new Stu("a", "bj", 90), new Stu("b", "bj", 80), new Stu("c", "sh", 70));
        System.out.println(xs.stream().collect(Collectors.groupingBy(Stu::city, Collectors.counting())));
        System.out.println(xs.stream().collect(Collectors.groupingBy(Stu::city,
            Collectors.averagingInt(Stu::score))));
        System.out.println(xs.stream().map(Stu::name).collect(Collectors.joining(",", "[", "]")));
        System.out.println(xs.stream().collect(Collectors.toMap(Stu::name, Stu::score, (a, b) -> b)));
        System.out.println(xs.stream().collect(Collectors.partitioningBy(s -> s.score() >= 80)).size());
    }
}

import java.util.*;
import java.util.stream.*;
public class Parallel {
    public static void main(String[] args) {
        List<Integer> big = IntStream.rangeClosed(1, 1_000_000).boxed().toList();
        long t1 = System.nanoTime();
        long s1 = big.stream().mapToLong(i -> (long) i * i).sum();
        long t2 = System.nanoTime();
        long s2 = big.parallelStream().mapToLong(i -> (long) i * i).sum();
        long t3 = System.nanoTime();
        System.out.println(s1 == s2);
        System.out.println("seq " + (t2 - t1) / 1_000_000 + "ms par " + (t3 - t2) / 1_000_000 + "ms");
    }
}

